public final class Sensor implements AutoCloseable {
    static { System.loadLibrary("sensor"); }
    private long handle;                       // native handle owned by the facade

    public Sensor(String path) { handle = nativeOpen(path); }
    @Override public void close() { if (handle != 0) { nativeClose(handle); handle = 0; } }

    private static native long nativeOpen(String path);
    private static native void nativeClose(long handle);
}
